46		if err != nil {
47			t.Fatalf("estimate with no usage: %v", err)
48		}
49		wantEstimate(t, e, EstimatedBill{
50			AccountID: "a", Estimated: true, Period: jan26, Terms: terms,
51			TotalUsage: 0, IncludedUnits: 10, OverageUnits: 0,
52			MonthlyFee: 1000, OverageFee: 0, Tax: 100, EstimatedTotalDue: 1100,
53		})
