55		// 接收 15 单位：超额 5、超额费 500、税 150、预计应付 1650。
56		if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "e1", At: utc(2026, 1, 12, 0, 0), Quantity: 15}); err != nil {
57			t.Fatal(err)
58		}
59		e, err = s.EstimateCurrentBill("a")
60		if err != nil {
61			t.Fatal(err)
62		}
