116		s, clk := newTestService(utc(2026, 1, 15, 12, 0))
117		mustPlan(t, s, Plan{ID: "p", MonthlyFee: 1000, IncludedUnits: 10, OveragePrice: 100, TaxRateBasisPoints: 1000})
118		mustAccount(t, s, "a")
119		if err := s.Subscribe("a", "p", utc(2026, 1, 1, 0, 0)); err != nil {
120			t.Fatal(err)
121		}
122		if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "e1", At: utc(2026, 1, 10, 0, 0), Quantity: 15}); err != nil {
123			t.Fatal(err)
124		}
125		if _, err := s.EstimateCurrentBill("a"); err != nil {
126			t.Fatal(err)
127		}
128	
129		// 不保存正式账单。
130		if _, err := s.GetBill("a", jan(2026)); !errors.Is(err, ErrBillNotFound) {
131			t.Fatalf("estimate saved a bill: %v", err)
132		}
133		// 不改变用量。
134		if u, _ := s.MonthlyUsage("a", jan(2026)); u.Total != 15 {
135			t.Fatalf("usage changed after estimate: %d", u.Total)
136		}
137		// 不关闭当月：预估之后同月新用量照常接收，再次预估反映新增累计。
138		clk.t = utc(2026, 1, 16, 0, 0)
139		if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "e2", At: utc(2026, 1, 16, 0, 0), Quantity: 3}); err != nil {
140			t.Fatalf("new usage after estimate rejected: %v", err)
141		}
142		e, err := s.EstimateCurrentBill("a")
143		if err != nil {
144			t.Fatal(err)
145		}
146		if e.TotalUsage != 18 || e.OverageUnits != 8 || e.OverageFee != 800 || e.EstimatedTotalDue != 1980 {
147			t.Fatalf("estimate did not reflect new usage: %+v", e)
148		}
149		// 重复预估结果一致、不累积任何状态。
150		e2, err := s.EstimateCurrentBill("a")
151		if err != nil || e2 != e {
152			t.Fatalf("repeated estimate differs: %+v %v", e2, err)
153		}
154		// 预估不影响状态中的账单列表。
155		st, err := s.Status("a")
156		if err != nil {
157			t.Fatal(err)
158		}
159		if len(st.Bills) != 0 || st.Suspended {
160			t.Fatalf("estimate changed status: %+v", st)
161		}
162	
163		// 跨月后一月仍未出账、可正常出账；二月预估只看二月用量（0），
164		// 不把一月用量带进来。
165		clk.t = utc(2026, 2, 10, 0, 0)
166		febEst, err := s.EstimateCurrentBill("a")
167		if err != nil {
168			t.Fatal(err)
169		}
170		if febEst.Period != feb(2026) || febEst.TotalUsage != 0 || febEst.OverageUnits != 0 ||
171			febEst.MonthlyFee != 1000 || febEst.Tax != 100 {
172			t.Fatalf("february estimate: %+v", febEst)
173		}
174		b, err := s.CreateBill("a", jan(2026))
175		if err != nil {
176			t.Fatal(err)
177		}
178		if b.TotalUsage != 18 {
179			t.Fatalf("january bill usage = %d, want 18", b.TotalUsage)
180		}
181	}
