286	func TestEstimateCurrentBillWhileSuspended(t *testing.T) {
287		s, clk := newTestService(utc(2026, 1, 1, 0, 0))
288		mustPlan(t, s, Plan{ID: "p", MonthlyFee: 1000, IncludedUnits: 10, OveragePrice: 100, TaxRateBasisPoints: 0})
289		mustAccount(t, s, "a")
290		if err := s.Subscribe("a", "p", utc(2026, 1, 1, 0, 0)); err != nil {
291			t.Fatal(err)
292		}
293		// 二月 5 日（一月账单截止 2 月 8 日之前）先接收 5 单位二月用量。
294		clk.t = utc(2026, 2, 5, 0, 0)
295		if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "e-feb", At: utc(2026, 2, 5, 0, 0), Quantity: 5}); err != nil {
296			t.Fatal(err)
297		}
298		// 过了截止时刻为一月出账：一月账单未付，账户欠费停用；订阅仍生效。
299		clk.t = utc(2026, 2, 10, 0, 0)
300		janBill, err := s.CreateBill("a", jan(2026))
301		if err != nil {
302			t.Fatal(err)
303		}
304		st, _ := s.Status("a")
305		if !st.Subscribed || !st.Suspended {
306			t.Fatalf("want subscribed+suspended, got %+v", st)
307		}
308	
309		// 停用期间仍可查询预估，包含停用前已接收的二月累计 5。
310		e, err := s.EstimateCurrentBill("a")
311		if err != nil {
312			t.Fatalf("estimate while suspended failed: %v", err)
313		}
314		if e.Period != feb(2026) || e.TotalUsage != 5 || e.MonthlyFee != 1000 || e.EstimatedTotalDue != 1000 {
315			t.Fatalf("estimate while suspended: %+v", e)
316		}
317		// 查询本身不能解除停用，也不改变新用量被拒绝的规则。
318		if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "e-new", At: utc(2026, 2, 10, 0, 0), Quantity: 1}); !errors.Is(err, ErrSuspended) {
319			t.Fatalf("new usage after estimate: %v", err)
320		}
321		st, _ = s.Status("a")
322		if !st.Suspended {
323			t.Fatal("estimate cleared suspension")
324		}
325		// 预估没有改变欠费账单。
326		cur, err := s.GetBill("a", jan(2026))
327		if err != nil || cur.Balance != janBill.TotalDue || cur.Settled {
328			t.Fatalf("overdue bill changed: %+v %v", cur, err)
329		}
330	
331		// 结清后预估照常，且二月累计仍是 5（被拒收的事件未累计）。
332		if _, err := s.RecordPayment("a", "pay-jan", jan(2026), janBill.TotalDue); err != nil {
333			t.Fatal(err)
334		}
335		e, err = s.EstimateCurrentBill("a")
336		if err != nil {
337			t.Fatal(err)
338		}
339		if e.TotalUsage != 5 || e.EstimatedTotalDue != 1000 {
340			t.Fatalf("estimate after payment: %+v", e)
341		}
342	}
